const state = {lang:(localStorage.getItem("reverfolio.lang") || localStorage.getItem("openecho.lang"))==="en"?"en":"zh",view:"overview",data:null,leases:new Map(),preview:null,importInput:"",busy:false,settingsQuery:"",settingsSelected:"",settingsExpanded:new Set(),settingsDraft:{},evidenceFilter:null,propagationWork:null,offlineMessage:"",websitePreview:null,websiteURL:"",devtoPreview:null};
const $ = id => document.getElementById(id);
const T = key => state.lang==="en" ? (LANG[key] || key) : key;
const E = value => String(value ?? "").replace(/[&<>"']/g, c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const fmt = value => value == null ? "—" : Number(value).toLocaleString(state.lang==="en"?"en-US":"zh-CN");
const dt = value => value ? new Date(value).toLocaleString(state.lang==="en"?"en-US":"zh-CN",{year:"numeric",month:"2-digit",day:"2-digit",hour:"2-digit",minute:"2-digit",...(pref("display.timezone")==="UTC"?{timeZone:"UTC"}:{})})+(pref("display.timezone")==="UTC"?" UTC":"") : "—";
const when = value => value ? new Date(value).toLocaleDateString(state.lang==="en"?"en-US":"zh-CN",pref("display.timezone")==="UTC"?{timeZone:"UTC"}:undefined) : "—";
const safeHref = value => {try {const u=new URL(value);return ["https:","http:"].includes(u.protocol)?E(u.href):"#";}catch{return "#";}};
const anchor = (url,label) => '<a href="'+safeHref(url)+'" target="_blank" rel="noopener noreferrer">'+E(label||url)+'</a>';
const tag = (label,cls="") => '<span class="badge '+E(cls)+'">'+E(label)+'</span>';
const uuid = () => crypto.randomUUID();
const selectWorks = () => state.data.works.map(w=>'<option value="'+w.id+'">'+E(w.title)+'</option>').join("");
// Both browser-extension panel and desktop browser consume the exact same UI.
// The trusted extension bundle supplies a fixed localhost origin in a meta tag.
// Regular web pages use their own origin, retaining HttpOnly same-site sessions.
const extensionMode = location.protocol==="chrome-extension:";
const apiOrigin = document.querySelector('meta[name="reverfolio-api-origin"]')?.content || location.origin;
const apiURL = path => new URL(path,apiOrigin).href;
if(extensionMode)document.documentElement.classList.add("reverfolio-extension");
// A native-message request is made before the first data read. The native host
// checks for an existing service and starts one only if needed.
let nativeReady=false;
let nativePending=null;
function requestNative(command){
 return new Promise((resolve,reject)=>{
  chrome.runtime.sendMessage({type:"reverfolio.bridge",command},reply=>{
   const error=chrome.runtime.lastError;
   if(error){reject(Error(T("本机启动器没有响应，请重新运行安装脚本。")+" "+error.message));return;}
   if(!reply?.ok){reject(Error(reply?.error||T("本机启动器没有响应，请重新运行安装脚本。")));return;}
   resolve(reply);
  });
 });
}
async function ensureLocalService(force=false){
 if(!extensionMode)return;
 if(nativeReady&&!force)return;
 // Keep existing installs usable when the service is already running, even
 // before Native Messaging is registered (including Linux/macOS installs).
 if(!force) {
  try {
   await api("/api/runtime");
   nativeReady=true;
   return;
  } catch(error) {
   // A 401 is an authorization/setup error, not a reason to start a duplicate.
   if(String(error?.message||"").includes("未获授权"))throw error;
  }
 }
 if(!nativePending){
  nativePending=requestNative("ensure_bridge").then(result=>{nativeReady=true;return result;}).finally(()=>{nativePending=null;});
 }
 return nativePending;
}
function offlineView(){
 return '<section class="panel offline-panel"><h2>'+E(T("服务未连接"))+'</h2>'+
 '<p>'+E(state.offlineMessage||T("服务尚未启动"))+'</p>'+
 '<p class="meta">'+E(T("启动服务无需保留控制台窗口；如失败，请检查本地安装与端口。"))+'</p>'+
 '<div class="btn-row">'+(extensionMode?'<button class="btn btn-primary" data-action="start-local-service">'+E(T("启动本地服务"))+'</button>':'')+
 '<button class="btn btn-secondary" data-action="refresh">'+E(T("重试连接"))+'</button></div></section>';
}
async function api(url,opts={}) {
  const extensionHeader = extensionMode ? {"X-Reverfolio-Extension-Access":String(window.REVERFOLIO_EXTENSION_ACCESS||"")} : {};
  const headers = {"Content-Type":"application/json",...extensionHeader,...(opts.method && opts.method!=="GET" ? {"X-Reverfolio-UI":"1"} : {}),...(opts.headers||{})};
  const response=await fetch(apiURL(url),{credentials:extensionMode?"omit":"same-origin",...opts,headers});
  if(!response.ok) {
    if(response.status===401) throw Error(extensionMode ? "Reverfolio 扩展未获授权：运行 Start-Reverfolio.cmd 初始化本地访问，然后在 Edge 扩展管理页面重新加载扩展。" : T("请刷新页面重新建立本地会话"));
    throw Error((await response.text()).trim().slice(0,240)+" (HTTP "+response.status+")");
  }
  return response.json();
}
async function send(name,data) {return api("/api/actions/"+name,{method:"POST",body:JSON.stringify({...data,request_id:uuid()})});}
function notification(message,error=false) {
  const x=$("notice");x.textContent=message;x.className="notice active"+(error?" error":"");
  window.clearTimeout(notification.timer);notification.timer=setTimeout(()=>x.className="notice",7000);
}
async function act(operation,successMessage=T("已保存并更新")) {
  if(state.busy)return;state.busy=true;document.body.classList.add("busy");
  try {await operation();await refresh(false);notification(successMessage);}
  catch(err){notification(String(err.message||err),true);}
  finally {state.busy=false;document.body.classList.remove("busy");}
}
async function refresh(showMessage=true){
 try{
  await ensureLocalService();
  const [works,report,mentions,tasks,audit,settings,runtime,sources,catalog,dashboard,websites,platformDashboard]=await Promise.all([
    api("/api/works"),api("/api/report"),api("/api/mentions"),api("/api/tasks"),api("/api/audit"),api("/api/settings"),api("/api/runtime"),api("/api/site-sources"),api("/api/catalog"),api("/api/dashboard"),api("/api/website-sources"),api("/api/platform-dashboard")
  ]);
  const pairs=await Promise.all(works.map(async w=>[w.id,await api("/api/works/"+w.id+"/channels")]));
  state.data={works,report,mentions,tasks,audit,settings,runtime,sources,catalog,dashboard,websites,platformDashboard,channels:new Map(pairs)};
  state.offlineMessage="";
  state.lang=pref("interface.language","zh-CN")==="en"?"en":"zh";
  render();
  if(showMessage)notification(T("数据读取成功"));
 }catch(error){
  nativeReady=false;
  state.data=null;
  state.offlineMessage=String(error?.message||error);
  render();
  throw error;
 }
}
function navRender(){
  $("navigation").innerHTML=nav.map(([id,icon,label])=>
   '<button class="nav-button '+(state.view===id?"active":"")+'" data-action="navigate" data-view="'+id+'" title="'+E(T(label))+'" aria-label="'+E(T(label))+'"><span class="nav-icon" aria-hidden="true">'+icon+'</span><span>'+T(label)+'</span></button>').join("");
}
function shellRender(){
  document.documentElement.lang=state.lang==="en"?"en":"zh-CN";
  const current=nav.find(x=>x[0]===state.view)||nav[0];
  $("page-title").textContent=T(current[2]);$("page-subtitle").textContent=T(current[3]);
  $("locale-button").textContent=state.lang==="zh"?"EN":"中文";
  const newTab=$("open-browser-tab");
  if(newTab)newTab.hidden=!extensionMode;
  document.title="Reverfolio · "+T(current[2]);
  document.querySelectorAll("[data-i18n]").forEach(node=>node.textContent=T(node.dataset.i18n));
  const indicator=document.querySelector(".sidebar-status .pill");
  if(indicator)indicator.textContent=state.offlineMessage?T("服务未连接"):T("已连接");
  document.querySelectorAll(".sidebar-status .online-dot,.topbar .online-dot").forEach(dot=>dot.classList.toggle("offline",!!state.offlineMessage));
  navRender();
}
function render(){
  shellRender();if(!state.data){$("view").innerHTML=state.offlineMessage?offlineView():'<div class="loading">Loading…</div>';return;}
  document.body.classList.toggle("compact-layout",pref("appearance.compact")==="true");
  const pages={overview:overviewView,works:worksView,websites:websiteSourcesView,platforms:platformsView,channels:channelsView,propagation:propagationView,evidence:evidenceView,tasks:tasksView,history:historyView,settings:settingsView};
  $("view").innerHTML=pages[state.view]();
}
const heading=(title,sub="",right="")=>'<div class="section-header"><div><h2>'+T(title)+'</h2>'+(sub?'<p>'+T(sub)+'</p>':"")+'</div>'+right+'</div>';
const stat=(title,value,note,primary=false)=>'<div class="stat-card'+(primary?' primary':'')+'"><div class="stat-label">'+T(title)+'</div><div class="stat-value">'+fmt(value)+'</div><div class="stat-hint">'+T(note)+'</div></div>';

function observationStatus(p){
 const v=p.valid_metrics||{};
 return '<p class="meta">'+E(settingsLabel(["最近尝试状态","Latest attempt status"]))+': '+E(p.latest?.state||'unknown')+'</p>'+Object.entries(v).map(([key,point])=>'<p class="meta">'+E(key)+' · '+E(settingsLabel(["有效观测时间","Valid observation at"]))+': '+dt(point.observed_at)+(point.observed_at!==p.latest?.captured_at?' · '+E(settingsLabel(["历史值","Historical value"])):'')+'</p>').join('');
}

function projects(){
 return state.data.report.report.sources.map(s=>{
  const x=s.latest,d=s.last_release?.downloads||x?.downloads,v=s.valid_metrics||{};
  return {...s,changes:s.last_comparable_changes,downloads:d?(pref("github.download_scope")==="installers"?d.packages:d.total):null,stars:v.stars?.value??x?.stars??null,clones:v.clones?.value??x?.traffic?.clones?.count??null,snapshot:x?.captured_at||""};
 });
}
function downloadLabel(){return pref("github.download_scope")==="installers"?settingsLabel(["程序包下载","Package downloads"]):T("发布资产下载");}
function downloadDetails(p){
 const release=p.last_release||p.latest;
 const d=release?.downloads;
 if(!d)return '<p class="muted">'+settingsLabel(["Release 数据不可用","Release data unavailable"])+'</p>';
 const kinds={package:settingsLabel(["程序包","Package"]),source:settingsLabel(["源码","Source"]),auxiliary:settingsLabel(["辅助文件","Auxiliary"]),other:settingsLabel(["其他／未分类","Other / unclassified"])};
 const changes=p.changes,delta=changes?.known_downloads;
 return '<details class="download-breakdown"><summary>'+settingsLabel(["下载分类与区间变化","Download breakdown & interval changes"])+'</summary>'+
 '<p class="meta">'+E(settingsLabel(["按文件名推断，不能代表安装或真实用户。","Inferred from filenames; not installations or verified users."]))+'</p>'+
 '<p>'+E(settingsLabel(["程序包","Packages"]))+': '+fmt(d.packages)+' · '+E(kinds.source)+': '+fmt(d.source)+' · '+E(kinds.auxiliary)+': '+fmt(d.auxiliary)+' · '+E(kinds.other)+': '+fmt(d.other)+'</p>'+
 (delta?'<p>'+E(settingsLabel(["已知区间增量","Known interval increase"]))+': +'+fmt(delta.total)+' ('+E(kinds.package)+': +'+fmt(delta.packages)+'); '+E(settingsLabel(["未知增量附件","Assets with unknown changes"]))+': '+fmt(changes.unknown_assets)+'</p><p class="meta">'+dt(changes.from)+' → '+dt(changes.to)+'</p>':'<p class="meta">'+E(settingsLabel(["尚无两个可比较的完整 Release 快照。","Two complete release observations are required for a comparison."]))+'</p>')+
 '<div class="table-wrap"><table class="data-table"><thead><tr><th>'+settingsLabel(["附件","Asset"])+'</th><th>'+settingsLabel(["分类","Category"])+'</th><th>'+settingsLabel(["累计下载","Cumulative downloads"])+'</th></tr></thead><tbody>'+
 (release.assets||[]).map(a=>'<tr><td style="overflow-wrap:anywhere">'+E(a.name)+'</td><td>'+E(kinds[a.category]||kinds.other)+'</td><td>'+fmt(a.download_count)+'</td></tr>').join("")+'</tbody></table></div></details>';
}
function overviewView(){
 const {works,report,mentions}=state.data,summary=report.report,rows=projects();
 const verified=mentions.filter(m=>m.state==="verified").slice(-Number(pref("overview.evidence_limit","4"))).reverse();
 const githubView=pref("overview.show_github")!=="false" ?
  heading("GitHub 项目活动","统计为累计发布资产下载量；不等于真实安装用户")+
  '<div class="activity-grid">'+rows.slice().sort((a,b)=>b.downloads+b.clones-a.downloads-a.clones).map(p=>
    '<article class="activity-card"><div class="activity-top">'+
      '<div class="activity-icon" aria-hidden="true">⌘</div>'+
      '<div class="activity-heading"><strong>'+anchor("https://github.com/"+p.repository,p.title)+'</strong>'+
      '<small>'+E(p.repository)+'</small></div>'+
      '<span class="activity-external">'+anchor("https://github.com/"+p.repository,"↗")+'</span></div>'+
      '<div class="activity-stat-row">'+
      '<div><span>'+downloadLabel()+'</span><strong>'+fmt(p.downloads)+'</strong></div>'+
      '<div><span>'+T("近期克隆")+'</span><strong>'+fmt(p.clones)+'</strong></div>'+
      '<div><span>'+T("Star")+'</span><strong>'+fmt(p.stars)+'</strong></div>'+
      '</div><div class="activity-foot"><span>'+T("最近采集")+'</span><time>'+dt(p.snapshot)+'</time></div>'+observationStatus(p)+downloadDetails(p)+'</article>'
  ).join("")+'</div>'+
  '<details class="panel activity-details"><summary>'+settingsLabel(["查看 GitHub 原始统计表","View the GitHub metrics table"])+'</summary>'+
  '<div class="table-wrap"><table class="data-table"><thead><tr><th>'+T("仓库")+'</th><th>'+(pref("github.download_scope")==="installers"?settingsLabel(["安装包下载","Installable downloads"]):T("发布资产下载"))+'</th><th>'+T("近期克隆")+'</th><th>'+T("Star")+'</th><th>'+T("最近采集")+'</th></tr></thead><tbody>'+
  rows.map(p=>'<tr><td>'+anchor("https://github.com/"+p.repository,p.title)+'</td><td class="num">'+fmt(p.downloads)+'</td><td class="num">'+fmt(p.clones)+'</td><td class="num">'+fmt(p.stars)+'</td><td class="muted">'+dt(p.snapshot)+'</td></tr>').join("")+
  '</tbody></table></div></details>'+
  '<p class="kpi-note">'+T("离线优先。GitHub 下载、克隆与网站访客标识都不能等同于真实使用者。")+'</p>' : "";
 const evidence=pref("overview.show_evidence")!=="false" ?
  '<div>'+heading("外部影响证据","已确认的第三方引用与采用记录",'<button class="btn btn-sm" data-action="navigate" data-view="evidence">'+T("查看更多")+'</button>')+
  '<div class="panel">'+(verified.length?verified.map(m=>'<div class="list-row"><div class="status-line">'+tag(T("已审核"),"verified")+' <strong>'+E(works.find(w=>w.id===m.work_id)?.title||"")+'</strong></div><p class="muted">'+E(m.evidence?.at(-1)?.quote||"")+'</p><div class="evidence-url">'+anchor(m.url)+'</div></div>').join(""):'<div class="empty">'+T("暂无公开链接")+'</div>')+'</div></div>' : "";
 const history=pref("overview.show_history")!=="false" ?
  '<div>'+heading("最近统计与限制","历史统计不自动变成实时数据")+'<div class="panel">'+
  (summary.history||[]).filter(r=>["search_impressions","search_clicks","pageviews_approx","visitor_identifiers"].includes(r.metric)).slice(0,6)
   .map(r=>'<div class="list-row"><div class="status-line"><strong>'+E(r.metric)+'</strong><span class="muted">'+fmt(r.value)+'</span></div><div class="subtle">'+E(r.scope)+'</div></div>').join("")+
  '<p class="kpi-note">'+T("历史统计不自动变成实时数据")+'</p></div></div>':"";
 const platform=state.data.platformDashboard||{accounts:[],publications:[]};
 const platformSummary=platform.accounts.length?
  heading(settingsLabel(["创作者平台观察","Creator platform observations"]),settingsLabel(["账号关注与文章浏览严格分开，缺失不等于零","Account subscriptions and article views are separate; missing is not zero"]),'<button class="btn btn-sm" data-action="navigate" data-view="platforms">'+E(settingsLabel(["查看平台详情","View platform details"]))+'</button>')+
  '<div class="activity-grid">'+platform.accounts.map(a=>'<article class="activity-card"><strong>'+anchor(a.account.profile_url,a.account.platform+' · @'+a.account.username)+'</strong><div class="activity-stat-row"><div><span>'+E(settingsLabel(["粉丝","Followers"]))+'</span><strong>'+metricValue(a.latest,"followers")+'</strong></div><div><span>'+E(settingsLabel(["已关联文章","Linked posts"]))+'</span><strong>'+fmt(platform.publications.filter(p=>p.publication.account_id===a.account.id).length)+'</strong></div></div><p class="meta">'+dt(a.last_run?.captured_at)+'</p>'+metricHistory(a.history,"followers",settingsLabel(["粉丝历史","Follower history"]))+'</article>').join('')+'</div>':'';
 return '<div class="toolbar"><div class="muted">'+T("历史统计不自动变成实时数据")+'</div><div class="btn-row"><button class="btn btn-sm" data-action="export-md">Markdown</button><button class="btn btn-sm" data-action="export-json">JSON</button></div></div><div class="stat-grid">'+
  stat("已登记作品",works.length,"包括项目、文章及网站")+
  stat("验证页面",summary.verified_pages,"仅统计审核通过的原始页面",true)+
  stat("传播事件",summary.third_party_events,"同一事件不重复计数")+
  stat("待审核线索",summary.pending,"需要再次核查原始来源")+'</div>'+
  impactDashboardView()+platformSummary+githubView+liveSourcesView()+(evidence||history?'<div class="grid-2">'+evidence+history+'</div>':"");
}
