function propagationView(){
 const works=state.data.works||[],channels=state.data.channels||new Map(),mentions=state.data.mentions||[];
 const siteHost=url=>{try{return new URL(url).hostname.toLowerCase();}catch{return "";}};
 const canonical=w=>w.kind==="project"?"https://github.com/"+w.repository:w.canonical_url;
 const eligible=works.filter(w=>canonical(w) && ((channels.get(w.id)||[]).length || mentions.some(m=>m.work_id===w.id)));
 const impact=w=>(channels.get(w.id)||[]).length+3*mentions.filter(m=>m.work_id===w.id&&m.state==="verified"&&m.origin==="third_party").length;
 eligible.sort((a,b)=>impact(b)-impact(a)||a.id-b.id);
 const active=eligible.find(w=>String(w.id)===String(state.propagationWork))||eligible[0];
 const label=(zh,en)=>settingsLabel([zh,en]);
 const introduction=heading(label("传播路径","Propagation paths"),label("公开链接只是作品关联；只有经审核的第三方原始证据才代表已核实传播。","Public URLs are associations; only reviewed original third-party evidence confirms propagation."));
 if(!eligible.length)return introduction+'<div class="panel empty">'+E(label("尚无可展示的公开渠道或引用证据。","No linked public URLs or evidence yet."))+'</div>';
 const selected='<label class="field propagation-picker"><span>'+E(label("选择作品","Select work"))+'</span><select id="propagation-select" aria-label="'+E(label("选择作品","Select work"))+'">'+eligible.map(w=>'<option value="'+w.id+'"'+(w.id===active.id?" selected":"")+'>'+E(w.title)+'</option>').join("")+'</select></label>';
 const allChannels=channels.get(active.id)||[],home=canonical(active),host=siteHost(home);
 const firstParty=allChannels.filter(c=>siteHost(c.url)===host&&c.url!==home);
 const distributed=allChannels.filter(c=>siteHost(c.url)!==host);
 const verified=mentions.filter(m=>m.work_id===active.id&&m.origin==="third_party"&&m.state==="verified");
 const groups=new Set(),events=[];
 for(const m of verified){
  const key=m.event_key||"mention-"+m.id;
  if(groups.has(key))continue;
  groups.add(key);
  const observed=(m.evidence||[]).map(x=>x.observed_at).filter(Boolean).sort()[0]||m.discovered_at;
  events.push({...m,observed});
 }
 events.sort((a,b)=>String(a.observed||"").localeCompare(String(b.observed||"")));
 const missing='<p class="meta">'+E(label("尚无已登记记录，不代表实际为零。","Nothing registered; this does not imply zero activity."))+'</p>';
 const linked=items=>items.length?'<ul class="propagation-links">'+items.map(c=>'<li><span class="propagation-lang">'+E(c.language||"—")+'</span> '+anchor(c.url,c.platform||siteHost(c.url))+'<small>'+E(c.url)+'</small></li>').join("")+'</ul>':missing;
 const pathNode=(name,count,content)=>'<section class="propagation-node"><div class="propagation-node-head"><h3>'+E(name)+'</h3><strong>'+fmt(count)+'</strong></div>'+content+'</section>';
 const source=pathNode(label("原文／主项目","Canonical work"),1,'<div class="propagation-main-link">'+anchor(home,active.title)+'</div><p class="meta">'+E(host)+'</p>');
 const originals=pathNode(label("同站语言版本","First-party language versions"),firstParty.length,linked(firstParty));
 const channelsNode=pathNode(label("外部分发链接","External distribution URLs"),distributed.length,linked(distributed));
 const evidence=pathNode(label("已核实第三方事件","Verified third-party events"),events.length,events.length?'<p class="meta">'+E(label("基于审核状态与事件标识去重，不是独立读者数。","Deduplicated by review state and event key; not an audience count."))+'</p>':missing);
 const timeline=events.length?'<ol class="propagation-timeline">'+events.map(m=>'<li><time>'+E(label("首次观测","First observed"))+' · '+dt(m.observed)+'</time><div><strong>'+E(m.actor_name||label("未知作者","Unknown author"))+' · '+E(m.type)+'</strong><p>'+anchor(m.url,m.url)+'</p><small>'+E(label("审核时间","Verified at"))+' · '+dt(m.verified_at)+'</small></div></li>').join("")+'</ol>':'<p class="panel meta">'+E(label("暂无经审核的第三方传播事件；这不表示没有人引用。","No verified third-party propagation recorded; absence is not proof of no citations."))+'</p>';
 return introduction+'<div class="panel">'+selected+'<p class="meta">'+E(label("流程展示的是关联关系，不按发布日期排序：渠道尚未记录发布时间。","This is an association map, not a publication chronology: channel publish dates are not stored."))+'</p></div>'+
 '<div class="propagation-flow">'+source+originals+channelsNode+evidence+'</div>'+
 heading(label("第三方传播观测时间线","Third-party evidence timeline"),label("仅展示审核通过的原始证据；日期为首次观测和审核时间，不是原始发布时间。","Reviewed original evidence only; dates describe observation and verification, not original publication."))+
 timeline;
}
function evidenceView(){
 const works=state.data.works;
 const labels={mention:"提及",citation:"引用",adoption:"采用",repost:"转载",rewrite:"改写",comment:"评论",aggregation:"聚合",publication:"发布"};
 const filter=state.evidenceFilter||pref("evidence.default_filter","all");
 const list=state.data.mentions.filter(m=>filter==="all"||m.state===filter).slice().reverse().map(m=>{
  const title=works.find(w=>w.id===m.work_id)?.title||String(m.work_id);
  const code=m.state==="verified"?"已审核":m.state==="pending"?"待审核":m.state==="rejected"?"已拒绝":"已失效";
  const pieces=m.evidence||[];
  return '<article class="evidence-item filterable" data-search="'+E([title,m.url,m.actor_name,m.state,m.type].join(" ").toLowerCase())+'">'+
  '<div class="evidence-head"><h3>'+E(title)+' · '+T(labels[m.type]||m.type)+'</h3>'+tag(T(code),m.state)+'</div>'+
  '<div class="card-sub" style="margin:7px 0">'+T("作者名称")+': '+E(m.actor_name||"—")+' · '+T("来源属性")+': '+T(m.origin==="third_party"?"第三方":m.origin==="self"?"本人":m.origin==="automated"?"自动生成":"未知")+'</div>'+
  '<div class="evidence-url">'+anchor(m.url)+'</div>'+
  pieces.map(x=>'<blockquote>'+E(x.quote)+'</blockquote><div class="subtle">'+E(x.source_kind)+' · '+dt(x.observed_at)+'</div>').join("")+
  '<div class="evidence-actions" style="margin-top:13px"><input class="inline-input" data-reason="'+m.id+'" placeholder="'+T("审核理由")+'" aria-label="'+T("审核理由")+'">'+
  '<button class="btn btn-sm" data-action="review" data-id="'+m.id+'" data-state="verified">'+T("审核通过")+'</button>'+
  '<button class="btn btn-sm btn-danger" data-action="review" data-id="'+m.id+'" data-state="rejected">'+T("拒绝")+'</button>'+
  '<input class="inline-input" data-event="'+m.id+'" value="'+E(m.event_key||"")+'" placeholder="'+T("关联事件标识")+'">'+
  '<button class="btn btn-sm" data-action="group" data-id="'+m.id+'">'+T("关联事件标识")+'</button></div>'+
  '</article>';
 }).join("");
 return heading("引用与采用","审核第三方引用与实际采用的原始证据")+
 '<div class="toolbar"><input class="search" data-filter placeholder="'+T("输入关键词筛选")+'"><select class="inline-input" id="evidence-filter" aria-label="'+T("筛选")+'">'+[["all","全部"],["pending","待审核"],["verified","已审核"]].map(([value,label])=>'<option value="'+value+'" '+(filter===value?"selected":"")+'>'+T(label)+'</option>').join("")+'</select><span class="muted">'+fmt(state.data.mentions.length)+'</span></div>'+
 '<div class="evidence-list">'+(list||'<div class="panel empty">'+T("无可用数据")+'</div>')+'</div>'+identityPanel()+
 heading("新建引用线索")+
 '<div class="panel"><form data-form="mention"><div class="form-grid">'+workSelection()+
 select("引用类型","type",Object.entries(labels).map(([id,text])=>[id,text]))+
 select("来源属性","origin",[["third_party","第三方"],["self","本人"],["automated","自动生成"],["unknown","未知"]])+
 select("生成方式","generation",[["unknown","未知"],["human","人工"],["ai","AI 生成"]])+
 input("作者名称","actor_name")+
 input("作者身份 URL","actor_key","url","https://")+
 input("关联事件标识","event_key")+
 select("证据来源","source_kind",[["secondary_report","二手报告（不能直接验证）"],["web","原始网页"],["api","原始 API"]])+
 '<label class="field full"><span>'+T("链接地址")+'</span><input type="url" name="url" required placeholder="https://"></label>'+
 '<label class="field full"><span>'+T("短证据说明")+'</span><textarea name="quote" required maxlength="1200"></textarea></label></div>'+
 '<div class="form-actions"><button class="btn btn-primary">'+T("提交待审核")+'</button></div></form></div>';
}
function liveSourcesView(){
 const runs=state.data.report.report.provider_runs||[];
 if(!runs.length)return '';
 const metricLabel=name=>({pageviews:settingsLabel(["页面浏览","Pageviews"]),visitor_identifiers:settingsLabel(["访客标识","Visitor identifiers"]),sessions:settingsLabel(["会话","Sessions"]),search_clicks:settingsLabel(["搜索点击","Search clicks"]),search_impressions:settingsLabel(["搜索曝光","Search impressions"]),ctr:settingsLabel(["点击率","CTR"]),average_position:settingsLabel(["平均排名","Average position"])})[name]||name;
 return heading(settingsLabel(["站点数据源观测","Site analytics observations"]))+'<div class="grid-cards">'+runs.map(r=>{
  const metrics=new Map();for(const m of r.metrics){const old=metrics.get(m.metric);if(!old)metrics.set(m.metric,{...m});else if(r.provider==='bing')old.value+=m.value;}
  return '<article class="mini-card"><div class="work-header"><h3>'+E(r.source_id)+'</h3>'+tag(r.state,r.state)+'</div><p class="meta">'+E(r.provider)+' · '+dt(r.captured_at)+'</p>'+(r.problem?'<p>'+E(r.problem)+'</p>':'')+[...metrics.values()].map(m=>'<p><strong>'+E(metricLabel(m.metric))+': '+(m.unit==='ratio'?fmt(m.value*100)+'%':fmt(m.value))+'</strong></p>').join('')+
  (r.metrics.length?'<p class="meta">'+E(settingsLabel(["保留独立来源及时间范围，不合并成独立读者数。","Sources and periods stay separate; no unique-reader inference."]))+'</p><details><summary>'+E(settingsLabel(["日期、口径与原始观测","Dates, scope and observations"]))+'</summary>'+r.metrics.map(m=>'<p>'+E(metricLabel(m.metric))+': '+fmt(m.value)+' '+E(m.unit)+'</p><p class="meta">'+dt(m.period_start)+' → '+dt(m.period_end)+' · '+E(m.timezone)+'</p><p class="meta">'+E(m.scope)+'</p>').join('')+'</details>':'')+'</article>';
 }).join('')+'</div>';
}
